import re, pathlib
PK = {"study","features","eqdata","forecast","agents"}
TYPE = re.compile(r"(?<![\w.])(?:[a-z][a-z0-9_]*\.)*[A-Z][a-z0-9]+(?:[A-Z][A-Za-z0-9]*)*\b")
docs = {p.parent.name: p for p in pathlib.Path("docs/packages").glob("*/contract.md")}
texts = {k: v.read_text() for k, v in docs.items()}
def sections():
    for pkg, t in texts.items():
        for m in re.finditer(r"^### ([a-z_]+)\.(\w+): ", t, re.M):
            yield pkg, m.group(1), m.group(2)
idx = {}
for pkg, comp, name in sections():
    idx.setdefault(name, []).append((pkg, f"{comp}.{name}"))
def find(name, prefer):
    if "." in name:
        q, n = name.rsplit(".", 1); q = q.replace("eqdata_", "")
        c = [x for x in idx.get(n, []) if x[0] == q or x[1].startswith(q + ".")]
    else:
        c = idx.get(name, [])
        p = [x for x in c if x[0] == prefer]
        c = p or c
    return c[0] if c else None
added = {}
for pl, pkg in [("PL-18", "forecast"), ("PL-19", "agents"), ("PL-06", "eqdata")]:
    t = pathlib.Path(f"docs/packages/{pkg}/pipelines.md").read_text()
    sec = t.split(f"## {pl}:")[1].split("\n## ")[0]
    for row in re.findall(r"^\| \d+ \| `([^`]+)` \| ([^|]+) \| ([^|]+) \|", sec, re.M):
        step, owner, io = row
        if pl == "PL-06" and step != "report_frame": continue
        o = owner.strip().split(".")[0]
        names = [(step, o if o in PK else pkg)] + [(n, pkg) for n in TYPE.findall(io.replace("`", ""))]
        for n, pref in names:
            hit = find(n, pref)
            if not hit: continue
            added.setdefault(hit, set()).add(pl)
for (pkg, sid), pls in added.items():
    t = texts[pkg]
    m = re.search(r"(^### " + re.escape(sid) + r": [\s\S]*?^- \*\*Used by:\*\* )(.*)$", t, re.M)
    if not m: print("no used-by", sid); continue
    line = m.group(2)
    new = [p for p in sorted(pls) if p not in line]
    if not new: continue
    line2 = line + (", " if re.search(r"; PL-", line) else "; ") + ", ".join(new)
    t = t[:m.start(2)] + line2 + t[m.end(2):]
    texts[pkg] = t
    print(sid, "+", new)
for k, v in docs.items(): v.write_text(texts[k])
EOF
